150:             ...this.dataParametrica,
151:             actividadesCalendario: this.actividadesCalendario,
152:           };*/
153:         }
154:       });
155: 
156:     // Mocking Data, ya que el servicio anterior (Get a horarioMiD) no funciona
157:     this.actividadesCalendario = {
158:       actividadesGestionHorario: [
159:         {
160:           FechaFin: '2028-12-31T23:59:59Z',
