54: export function setCookie(name: string, val: string) {
55:   const date = new Date();
56:   date.setTime(date.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 días
57:   document.cookie = `${name}=${val}; expires=${date.toUTCString()}; path=/`;
58: }
59: 
60: export function getCookie(name: string): string | undefined {
61:   const value = '; ' + document.cookie;
62:   const parts = value.split('; ' + name + '=');
63:   if (parts.length == 2) {
64:     return parts.pop()?.split(';').shift();
65:   }
66:   return undefined;
67: }

